window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[173]={"id":"173","numero":173,"titre":"Zoonoses","objectifs":[{"id":"173-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une zoonose","contenu":"<p>Une <span class=\"kw-def\">zoonose</span> est une <span class=\"kw-def\">maladie infectieuse transmise de l'animal à l'homme</span>. L'agent pathogène peut être de nature <span class=\"kw-etio\">bactérienne</span>, virale ou parasitaire — d'où la <span class=\"kw-def\">classification</span> en trois familles étiologiques.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Zoonoses du programme EDN</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Bactériennes</span></td><td><span class=\"kw-etio\">Fièvre Q</span> ; <span class=\"kw-etio\">pasteurellose</span> ; <span class=\"kw-etio\">maladie des griffes du chat</span> ; <span class=\"kw-etio\">borréliose de Lyme</span></td></tr>\n          <tr><td><span class=\"kw-def\">Virales</span></td><td><span class=\"kw-etio\">Rage</span></td></tr>\n          <tr><td><span class=\"kw-def\">Parasitaires</span></td><td><span class=\"kw-etio\">Toxoplasmose</span> ; <span class=\"kw-etio\">échinococcoses</span> (hydatique et alvéolaire) ; <span class=\"kw-etio\">leishmaniose</span></td></tr>\n        </tbody>\n      </table>\n      <p>Trois grands <strong>modes de transmission</strong> structurent l'item :</p>\n      <ul>\n        <li><strong>Transmission directe par un animal</strong> — <span class=\"kw-clinique\">morsure</span>, <span class=\"kw-clinique\">griffure</span>, <span class=\"kw-clinique\">léchage</span>, <span class=\"kw-def\">contact</span>, voie digestive ou inhalée.</li>\n        <li><strong>Transmission par un vecteur</strong> — un <span class=\"kw-etio\">arthropode</span> (<span class=\"kw-etio\">tique</span>, <span class=\"kw-etio\">phlébotome</span>) fait le passage de l'animal réservoir à l'homme.</li>\n        <li><strong>Pathologie d'inoculation</strong> — pénétration de l'agent à travers la peau ou <span class=\"kw-clinique\">les</span> muqueuses.</li>\n      </ul>","frequence":0},{"id":"173-2","rang":"B","rubrique":"Étiologies","titre":"Citer les principales étiologies bactériennes, virales et parasitaires des zoonoses","contenu":"<p><span class=\"kw-clinique\">Les</span> zoonoses du programme se répartissent en trois familles selon la nature de l'agent pathogène.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Zoonose</th><th>Agent</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Bactérienne</span></td><td><span class=\"kw-clinique\">Fièvre</span> Q</td><td><span class=\"kw-etio\">Coxiella burnetii</span></td></tr>\n          <tr><td><span class=\"kw-def\">Bactérienne</span></td><td>Pasteurellose</td><td><span class=\"kw-etio\">Pasteurella multocida</span></td></tr>\n          <tr><td><span class=\"kw-def\">Bactérienne</span></td><td>Maladie des griffes du chat</td><td><span class=\"kw-etio\">Bartonella henselae</span></td></tr>\n          <tr><td><span class=\"kw-def\">Bactérienne</span></td><td>Borréliose de Lyme</td><td><span class=\"kw-etio\">Borrelia</span> (<span class=\"kw-def\">spirochète</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Virale</span></td><td>Rage</td><td><span class=\"kw-etio\">Lyssavirus</span></td></tr>\n          <tr><td><span class=\"kw-def\">Parasitaire</span></td><td>Toxoplasmose</td><td><span class=\"kw-etio\">Toxoplasma gondii</span></td></tr>\n          <tr><td><span class=\"kw-def\">Parasitaire</span></td><td>Échinococcoses</td><td><span class=\"kw-etio\">Echinococcus granulosus</span> ; <span class=\"kw-etio\">E. multilocularis</span></td></tr>\n          <tr><td><span class=\"kw-def\">Parasitaire</span></td><td>Leishmaniose</td><td><span class=\"kw-etio\">Leishmania</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">🔁 <strong>Mnémo — <span class=\"kw-clinique\">les</span> 7 zoonoses directement transmises par un animal</strong> : « Fabrice Putain T'es Relou la ChattE » → <strong>F</strong>ièvre Q, <strong>P</strong>asteurellose, <strong>T</strong>oxoplasmose, <strong>R</strong>age, maladie des griffes du <strong>chat</strong>, <strong>é</strong>chinococcose hydatique et alvéolaire.</div>\n      <p><strong>Bactéries potentiellement transmises par <span class=\"kw-clinique\">morsure humaine</span></strong> : <span class=\"kw-etio\">S. aureus</span>, <span class=\"kw-etio\">H. influenzae</span>, <span class=\"kw-etio\">Eikenella corrodens</span>, <span class=\"kw-etio\">anaérobies</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p>","frequence":0},{"id":"173-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes lignes de l’épidémiologie des principales zoonoses","contenu":"<p>L'<span class=\"kw-def\">épidémiologie</span> des zoonoses se lit sur trois axes : le <strong>réservoir animal</strong>, le <strong>mode de transmission</strong> et la <strong>répartition géographique</strong>.</p>\n      <table >\n        <thead><tr><th>Zoonose</th><th>Réservoir</th><th>Transmission</th></tr></thead>\n        <tbody>\n          <tr><td>Borréliose de Lyme</td><td><span class=\"kw-etio\">Tiques Ixodes</span></td><td>Vecteur (<span class=\"kw-clinique\">piqûre de tique</span>)</td></tr>\n          <tr><td>Griffes du chat</td><td><span class=\"kw-etio\">Chat</span> (chaton)</td><td>Inoculation (<span class=\"kw-clinique\">griffure</span>, <span class=\"kw-clinique\">morsure</span>)</td></tr>\n          <tr><td>Pasteurellose</td><td><span class=\"kw-etio\">Chat</span>, <span class=\"kw-etio\">chien</span>, <span class=\"kw-etio\">oiseaux</span></td><td>Inoculation (<span class=\"kw-clinique\">morsure</span>, <span class=\"kw-clinique\">griffure</span>)</td></tr>\n          <tr><td>Toxoplasmose</td><td><span class=\"kw-etio\">Chat</span>, <span class=\"kw-etio\">ruminants</span>, <span class=\"kw-etio\">porcins</span></td><td>Directe (litière, viande mal cuite)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre</span> Q</td><td><span class=\"kw-etio\">Bovins</span>, <span class=\"kw-etio\">ovins</span>, <span class=\"kw-etio\">caprins</span></td><td>Directe (lait cru, aérosols) ou vecteur (<span class=\"kw-etio\">tiques</span>)</td></tr>\n          <tr><td>Rage</td><td><span class=\"kw-etio\">Canidés</span>, <span class=\"kw-etio\">renard</span>, <span class=\"kw-etio\">chauve-souris</span></td><td>Directe (<span class=\"kw-clinique\">morsure</span>, <span class=\"kw-clinique\">griffure</span>, <span class=\"kw-clinique\">léchage</span>)</td></tr>\n          <tr><td>Échinococcoses</td><td><span class=\"kw-etio\">Chien</span> (hydatique) ; <span class=\"kw-etio\">renard</span> (alvéolaire)</td><td>Directe ou indirecte (aliments souillés)</td></tr>\n          <tr><td>Leishmaniose</td><td><span class=\"kw-etio\">Chien</span>, <span class=\"kw-etio\">rongeurs</span></td><td>Vecteur (<span class=\"kw-etio\">phlébotome</span>)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">🎯 <strong><span class=\"kw-clinique\">Les</span> 3 zoonoses transmises par un vecteur</strong> : leishmaniose (<span class=\"kw-etio\">phlébotome</span>), borréliose de Lyme (<span class=\"kw-clinique\">tique Ixodes</span>), <span class=\"kw-clinique\">fièvre</span> Q (tiques).</div>\n      <div class=\"callout callout-info\">🎯 <strong><span class=\"kw-clinique\">Les</span> 4 zoonoses les plus fréquentes en France métropolitaine</strong> : borréliose de Lyme, maladie des griffes du chat, pasteurellose, toxoplasmose.</div>\n      <p><span class=\"kw-clinique\">Les</span> <strong>4 pathologies d'inoculation</strong> (transmission à travers la peau et les muqueuses) : borréliose de Lyme, maladie des griffes du chat, pasteurellose, leishmaniose.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p>","frequence":0},{"id":"173-4","rang":"A","rubrique":"Définition","titre":"Maladie des griffes du chat : connaître les généralités","contenu":"<p>La <span class=\"kw-etio\">maladie des griffes du chat</span> — aussi appelée <span class=\"kw-def\">lymphoréticulose bénigne d'inoculation</span> — est une zoonose <span class=\"kw-etio\">bactérienne</span> bénigne d'inoculation.</p>\n      <table >\n        <tbody>\n          <tr><td>Agent</td><td><span class=\"kw-etio\">Bartonella henselae</span> — bactérie <span class=\"kw-def\">intracellulaire</span>, non visible à la <span class=\"kw-bio\">coloration de Gram</span> (donc <strong>pas d'<span class=\"kw-bio\">hémocultures</span></strong>)</td></tr>\n          <tr><td>Réservoir</td><td>Le <strong><span class=\"kw-etio\">chat</span></strong>, surtout le <span class=\"kw-etio\">chaton</span> et le jeune chat</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Surtout l'<strong>enfant</strong> et le <strong>jeune adulte</strong></td></tr>\n          <tr><td>Incubation</td><td><span class=\"kw-chiffre\">2 à 3 semaines</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span></strong> en quatre temps :</p>\n      <ol>\n        <li><span class=\"kw-def\">Bactériémie</span> asymptomatique chez le chat, qui contamine ses griffes en se grattant des zones excoriées.</li>\n        <li>Transmission à l'homme : <span class=\"kw-clinique\">morsure</span>, <span class=\"kw-clinique\">griffure</span>, plus rarement léchage de plaie ou piqûre de puces du chat.</li>\n        <li>Multiplication de la bactérie dans le <span class=\"kw-clinique\">ganglion relais</span> du territoire de <span class=\"kw-ttt\">drainage</span> lymphatique.</li>\n        <li><span class=\"kw-clinique\">Adénopathie inflammatoire</span> : granulome épithélioïde sans <span class=\"kw-clinique\">nécrose</span> caséeuse, hyperplasie folliculaire, micro-<span class=\"kw-clinique\">abcès</span>.</li>\n      </ol>","frequence":1},{"id":"173-5","rang":"A","rubrique":"Diagnostic positif","titre":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","contenu":"<p>Le diagnostic de la maladie des griffes du chat associe une <strong>présentation clinique évocatrice</strong> et une <strong>confirmation microbiologique</strong>.</p>\n      <p><strong>Présentation clinique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Lésion primaire d'inoculation</span> (<span class=\"kw-chiffre\">50 %</span> des cas) : trace de morsure ou de griffure.</li>\n        <li><span class=\"kw-clinique\">Signes généraux discrets</span> (<span class=\"kw-chiffre\">50 %</span>) : <span class=\"kw-clinique\">céphalées</span>, <span class=\"kw-clinique\">asthénie</span>, fébricule, <span class=\"kw-clinique\">douleurs abdominales</span>.</li>\n        <li><span class=\"kw-clinique\">Lésion érythémateuse papuleuse</span> précédant l'<span class=\"kw-clinique\">adénopathie</span> (<span class=\"kw-chiffre\">50 %</span>), sur le territoire lymphatique de la <span class=\"kw-clinique\">lésion</span> cutanée.</li>\n        <li><span class=\"kw-clinique\">Adénopathie</span> du ganglion relais : unique (<span class=\"kw-chiffre\">50 %</span>) ou multiple sur un seul territoire unilatéral (<strong>cervical</strong>, <strong>axillaire</strong>, épitrochléen, inguinal) ; souvent volumineuse, ferme, mobile, <span class=\"kw-etio\">inflammatoire</span>, sensible, parfois en voie de fistulisation.</li>\n      </ul>\n      <p><strong>Formes cliniques particulières</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Syndrome oculo-glandulaire de Parinaud</span> — forme ophtalmique (<span class=\"kw-chiffre\">10 %</span>), surtout chez l'<strong>enfant</strong> : conjonctivite + <span class=\"kw-clinique\">adénopathie</span> prétragienne.</li>\n        <li>Endocardites à <span class=\"kw-bio\">hémocultures</span> négatives — rares.</li>\n      </ul>\n      <table >\n        <tbody>\n          <tr><td>Confirmation</td><td><span class=\"kw-bio\">Sérologie</span> en 1ʳᵉ intention (faible sensibilité — une <span class=\"kw-bio\">sérologie</span> négative n'élimine pas le diagnostic) ; en cas de doute : <span class=\"kw-bio\">PCR spécifique</span> sur <span class=\"kw-ttt\">exérèse</span> ou <span class=\"kw-bio\">biopsie</span> ganglionnaire (diagnostic de certitude), <span class=\"kw-bio\">histologie</span> montrant un granulome épithélioïde sans <span class=\"kw-clinique\">nécrose</span> caséeuse (forte présomption)</td></tr>\n          <tr><td>Traitement</td><td><span class=\"kw-ttt\">Azithromycine</span> pendant <span class=\"kw-chiffre\">5 jours</span> — <span class=\"kw-ttt\">antibiothérapie</span> discutée, l'<span class=\"kw-clinique\">évolution</span> étant spontanément favorable</td></tr>\n        </tbody>\n      </table>","frequence":1},{"id":"173-6","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modes de transmission de la maladie de Lyme","contenu":"<p>La <span class=\"kw-etio\">borréliose de Lyme</span> est la zoonose à vecteur la plus fréquente en France métropolitaine.</p>\n      <table >\n        <tbody>\n          <tr><td>Agents</td><td>Trois espèces du genre <span class=\"kw-etio\">Borrelia</span> — <span class=\"kw-etio\">B. burgdorferi</span>, <span class=\"kw-etio\">B. garinii</span>, <span class=\"kw-etio\">B. afzelii</span> — de la famille des <span class=\"kw-def\">spirochètes</span></td></tr>\n          <tr><td>Vecteur</td><td>Piqûre de <span class=\"kw-etio\">tique du genre Ixodes</span> : la bactérie est inoculée par régurgitation au décours d'un repas sanguin</td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Exposition lors de promenades en forêt, de travaux agricoles et forestiers</td></tr>\n          <tr><td>Géographie</td><td><span class=\"kw-clinique\">Les</span> différentes espèces ont des répartitions et des formes cliniques variables (les arthrites de Lyme sont rares en Europe, fréquentes aux USA)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ <strong>Piège.</strong> L'immunité spécifique <span class=\"kw-etio\">acquise</span> <span class=\"kw-alerte\">n'évite pas les réinfections</span>.</div>","frequence":0},{"id":"173-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les phases évolutives de la maladie de Lyme","contenu":"<p>L'<span class=\"kw-clinique\">évolution</span> de la maladie de Lyme se déroule classiquement en <strong>trois phases</strong>. La majorité des diagnostics est posée à la phase primaire ; mais l'<span class=\"kw-clinique\">érythème migrant</span> étant <strong>inconstant</strong>, <span class=\"kw-clinique\">les</span> phases disséminées peuvent révéler la maladie.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Délai</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr><td>Localisée précoce (primaire)</td><td><span class=\"kw-chiffre\">3-30 j</span> après la piqûre</td><td><span class=\"kw-clinique\">Érythème migrant</span> inconstant ; multiplication de la bactérie dans le derme</td></tr>\n          <tr><td>Disséminée précoce</td><td><span class=\"kw-chiffre\">&lt; 6 mois</span></td><td>Dissémination par voie hématogène :<br><strong>Neurologique :</strong> <span class=\"kw-clinique\">méningoradiculite</span> ; <span class=\"kw-def\">méningite</span> ; (rarement) <span class=\"kw-def\">encéphalite</span> ou <span class=\"kw-clinique\">myélite</span><br><strong>Articulaire :</strong> <span class=\"kw-clinique\">oligoarthrite des grosses articulations</span> (genou)<br><strong>Cardiaque :</strong> <span class=\"kw-clinique\">myocardite</span> ; <span class=\"kw-clinique\">troubles de conduction</span> (BAV) fluctuants<br><strong>Cutanée :</strong> <span class=\"kw-clinique\">lymphocytome borrélien</span><br><strong>Ophtalmologique :</strong> <span class=\"kw-clinique\">uvéites</span></td></tr>\n          <tr><td>Disséminée tardive (tertiaire)</td><td><span class=\"kw-chiffre\">&gt; 6 mois</span></td><td>Mécanisme immunologique probable :<br><strong>Cutanée :</strong> <span class=\"kw-clinique\">acrodermatite chronique atrophiante</span><br><strong>Neurologique :</strong> <span class=\"kw-clinique\">polyneuropathie sensitive</span> ; <span class=\"kw-clinique\">encéphalomyélite chronique</span><br><strong>Articulaire :</strong> <span class=\"kw-clinique\">mono ou oligo-arthrite chronique</span></td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/lyme-acrodermatite-atrophiante.png\" alt=\"Acrodermatite chronique atrophiante : placard cutané atrophique sur un membre, phase tertiaire de la maladie de Lyme\" loading=\"lazy\">\n        <figcaption>Acrodermatite chronique et atrophiante — manifestation cutanée quasi pathognomonique de la phase tertiaire de la borréliose de Lyme, évoquée surtout après <span class=\"kw-chiffre\">50 ans</span> : la <span class=\"kw-clinique\">lésion</span> évolue d'une phase œdémateuse vers l'atrophie. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 101 — <span class=\"kw-clinique\">Paralysie faciale</span></em></p>","frequence":1},{"id":"173-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de Lyme","contenu":"<p>Le diagnostic de la maladie de Lyme repose sur l'association <strong>manifestations cliniques compatibles + critère microbiologique</strong> — jamais sur la <span class=\"kw-bio\">sérologie</span> seule.</p>\n      <p><strong>Diagnostic clinique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Érythème migrant</span> : <span class=\"kw-clinique\">macule</span> érythémateuse qui s'étend par une bordure annulaire centrifuge active, à centre plus clair ; <strong><span class=\"kw-clinique\">indolore</span>, <span class=\"kw-clinique\">non prurigineux</span></strong> ; touche <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-clinique\">membres inférieurs</span></strong> dans <span class=\"kw-chiffre\">50 %</span> des cas. Il est <span class=\"kw-def\">pathognomonique</span> — aucun examen complémentaire n'est justifié à ce <span class=\"kw-def\">stade</span>.</li>\n        <li>Phases disséminées : manifestations neurologiques, articulaires, cardiaques et cutanées évocatrices.</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/lyme-em.jpg\" alt=\"Érythème migrant : macule érythémateuse annulaire à bordure active et centre plus clair\" loading=\"lazy\">\n        <figcaption><span class=\"kw-clinique\">Érythème</span> migrant — lésion pathognomonique de la phase primaire de la maladie de Lyme : bordure annulaire centrifuge, centre éclairci, point d'inoculation parfois visible. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <div class=\"callout callout-info\">⚠️ <strong>Drapeau / piège.</strong> Il n'y a <span class=\"kw-alerte\">pratiquement jamais de fièvre</span> dans la maladie de Lyme.</div>\n      <p><strong>Diagnostic <span class=\"kw-ttt\">biologique</span></strong> — la microbiologie repose essentiellement sur la <strong><span class=\"kw-bio\">sérologie</span> en 2 temps</strong> :</p>\n      <ol>\n        <li><span class=\"kw-bio\">ELISA</span> — test sensible, en <span class=\"kw-chiffre\">première intention</span>.</li>\n        <li><span class=\"kw-bio\">Western Blot</span> — test spécifique, en confirmation.</li>\n      </ol>\n      <p>La <span class=\"kw-bio\">sérologie</span> n'est positive que si <strong><span class=\"kw-clinique\">les</span> deux tests sont positifs</strong>. En cas de suspicion de <span class=\"kw-clinique\">neuroborréliose</span>, une <span class=\"kw-bio\">ponction lombaire</span> recherche les anticorps dans le <span class=\"kw-bio\">LCS</span> et le sang (<span class=\"kw-bio\">synthèse intrathécale</span> d'anticorps) ; on ne recherche pas <em>Borrelia</em> directement dans le <span class=\"kw-bio\">LCS</span> (mauvaise sensibilité). Pas d'<span class=\"kw-bio\">hémocultures</span> — les spirochètes ne sont pas visibles à la <span class=\"kw-bio\">coloration de Gram</span>.</p>\n      <div class=\"callout callout-info\">⚠️ <strong>Piège — faux positifs.</strong> La <span class=\"kw-bio\">sérologie</span> ne distingue pas l'infection active de la <span class=\"kw-def\">cicatrice sérologique</span> : jusqu'à <span class=\"kw-chiffre\">15-20 %</span> de positivité chez des sujets exposés asymptomatiques (chasseurs). Elle n'est <span class=\"kw-ci\">pas indiquée chez le sujet exposé asymptomatique</span> ni en <span class=\"kw-def\">dépistage</span> systématique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 101 — <span class=\"kw-clinique\">Paralysie faciale</span></em></p>","frequence":1},{"id":"173-9","rang":"B","rubrique":"Prise en charge","titre":"Maladie de Lyme : connaître les principes de prise en charge phase primaire","contenu":"<p>La prise en charge de la phase primaire (<span class=\"kw-clinique\">érythème</span> migrant) repose sur une <strong><span class=\"kw-ttt\">antibiothérapie</span></strong> qui accélère la guérison et réduit le risque de survenue d'une forme secondaire.</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Antibiotique</th><th>Durée</th></tr></thead>\n        <tbody>\n          <tr><td>Adulte</td><td><span class=\"kw-ttt\">Doxycycline</span> per os</td><td><span class=\"kw-chiffre\">14 jours</span> (10 j selon la HAS)</td></tr>\n          <tr><td>Enfant &lt;<span class=\"kw-chiffre\"> 8 ans</span></td><td><span class=\"kw-ttt\">Amoxicilline</span> per os — <span class=\"kw-ci\">doxycycline contre-indiquée</span></td><td><span class=\"kw-chiffre\">14 jours</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Prévention</strong> — essentiellement individuelle :</p>\n      <ul>\n        <li><strong>Primaire :</strong> vêtements longs, clairs, serrés aux chevilles et aux manches ; <span class=\"kw-ttt\">répulsifs cutanés</span> ; imprégnation vestimentaire d'<span class=\"kw-ttt\">insecticides</span>.</li>\n        <li><strong>Secondaire (après piqûre) :</strong> retrait rapide de la tique au <span class=\"kw-ttt\">tire-tique</span> ou à la pince à épiler, puis désinfection. <span class=\"kw-ci\">Pas d'antibioprophylaxie post-piqûre.</span></li>\n      </ul>","frequence":0},{"id":"173-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","contenu":"<p>La <span class=\"kw-etio\">pasteurellose</span> est une zoonose <span class=\"kw-etio\">bactérienne</span> d'inoculation, classiquement après une morsure ou une griffure de chat.</p>\n      <table >\n        <tbody>\n          <tr><td>Germe</td><td><span class=\"kw-etio\">Pasteurella multocida</span> — <span class=\"kw-def\">bacille à Gram négatif</span></td></tr>\n          <tr><td>Réservoir</td><td><span class=\"kw-etio\">Chat</span> <strong>++</strong>, <span class=\"kw-etio\">chien</span>, <span class=\"kw-etio\">oiseaux</span>, milieu extérieur</td></tr>\n          <tr><td>Transmission</td><td><span class=\"kw-clinique\">Morsure</span>, <span class=\"kw-clinique\">griffure</span>, piqûre végétale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ <strong>Discriminant clé.</strong> L'<span class=\"kw-alerte\">incubation est extrêmement rapide — 3 à 6 heures</span> avant le début des symptômes. Un délai aussi court oriente fortement vers la pasteurellose.</div>\n      <p><strong>Présentation clinique</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Aspect inflammatoire</span> autour de la plaie d'inoculation.</li>\n        <li><span class=\"kw-clinique\">Écoulement</span> possible.</li>\n        <li><span class=\"kw-clinique\">Lymphangite</span> et <span class=\"kw-clinique\">adénopathies</span> souvent associées.</li>\n      </ul>\n      <p><strong>Complications</strong> : <span class=\"kw-alerte\">cellulite</span>, <span class=\"kw-alerte\">phlegmon des gaines</span>, <span class=\"kw-alerte\">arthrite</span> ; <span class=\"kw-alerte\">bactériémie</span> chez l'immunodéprimé (notamment le cirrhotique).</p>\n      <table >\n        <tbody>\n          <tr><td>Microbiologie</td><td><span class=\"kw-bio\">Culture</span> sur prélèvements locaux et <span class=\"kw-bio\">hémocultures</span></td></tr>\n          <tr><td>Traitement</td><td><span class=\"kw-ttt\">Amoxicilline</span> pendant <span class=\"kw-chiffre\">7 jours</span> ; si <span class=\"kw-ci\">allergie</span> : céphalosporine ou <span class=\"kw-ttt\">doxycycline</span> (<span class=\"kw-clinique\">les</span> cyclines sont l'antibiotique de choix sur <em>Pasteurella multocida</em>)</td></tr>\n          <tr><td>Prévention</td><td>Désinfection de la plaie ; <span class=\"kw-ttt\">antibioprophylaxie</span> par <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span></td></tr>\n        </tbody>\n      </table>","frequence":4},{"id":"173-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la fièvre Q","contenu":"<p>La <span class=\"kw-def\">fièvre Q</span> est une zoonose <span class=\"kw-etio\">bactérienne</span> due à <span class=\"kw-etio\">Coxiella burnetii</span>, bactérie <span class=\"kw-def\">intracellulaire</span>.</p>\n      <table >\n        <tbody>\n          <tr><td>Réservoir</td><td>Placentas des animaux infectés — surtout <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">ruminants</span> (<span class=\"kw-etio\">bovins</span>, <span class=\"kw-etio\">ovins</span>, <span class=\"kw-etio\">caprins</span>)</td></tr>\n          <tr><td>Transmission</td><td><strong>Inhalée :</strong> aérosols de paille et de fumier contaminés ; <br><strong>Digestive :</strong> consommation de lait cru ; <br><strong>Vecteur :</strong> tiques</td></tr>\n        </tbody>\n      </table>\n      <p>Infection <span class=\"kw-clinique\">asymptomatique dans 60 %</span> des cas. Trois formes cliniques :</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td>Aiguë (la plus fréquente)</td><td>Incubation ~<span class=\"kw-chiffre\">3 semaines</span>, début pseudo-grippal, puis <span class=\"kw-clinique\">fièvre</span> isolée, <strong><span class=\"kw-def\">hépatite</span> fébrile</strong> (présentation la plus fréquente) ou pneumopathie interstitielle</td><td><span class=\"kw-ttt\">Doxycycline</span> pendant <span class=\"kw-chiffre\">2 à 3 semaines</span></td></tr>\n          <tr><td>Chronique</td><td><span class=\"kw-def\">Terrain</span> : immunodéprimé, porteur de <span class=\"kw-clinique\">lésion</span> valvulaire ou vasculaire → <span class=\"kw-alerte\">endocardite à hémocultures négatives</span>, infection vasculaire (anévrisme, prothèse)</td><td><span class=\"kw-ttt\">Doxycycline + hydroxychloroquine</span>, durée prolongée (<span class=\"kw-chiffre\">18 à 24 mois</span>)</td></tr>\n          <tr><td>Femme enceinte</td><td>Conséquences fœtales (fausses couches)</td><td><span class=\"kw-ttt\">Cotrimoxazole</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations biologiques</strong> : <span class=\"kw-bio\">thrombopénie</span>, <span class=\"kw-bio\">leuco-neutropénie</span> possible, <span class=\"kw-bio\">cytolyse hépatique</span>, allongement du <span class=\"kw-bio\">TCA</span> (<span class=\"kw-ttt\">anticoagulant</span> circulant).</p>\n      <p><strong>Microbiologie</strong> : <span class=\"kw-bio\">sérologie</span> de <em>Coxiella burnetii</em> — le type d'anticorps identifié oriente vers une forme chronique ; <span class=\"kw-bio\">PCR</span> et culture possibles en centre de référence.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 152 — <span class=\"kw-def\">Endocardite</span> infectieuse</em></p>","frequence":0},{"id":"173-12","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les modes de transmission de la rage","contenu":"<p>La <span class=\"kw-def\">rage</span> est une zoonose <span class=\"kw-etio\">virale</span>, constamment mortelle une fois déclarée.</p>\n      <table >\n        <tbody>\n          <tr><td>Agent</td><td><span class=\"kw-etio\">Lyssavirus</span> (famille des <em>Rhabdoviridae</em>) — virus <span class=\"kw-def\">neurotrope</span>, fragile, rapidement détruit dans le milieu extérieur</td></tr>\n          <tr><td>Réservoir</td><td><span class=\"kw-etio\">Canidés</span>, <span class=\"kw-etio\">renard</span>, <span class=\"kw-etio\">chauve-souris</span></td></tr>\n          <tr><td>Transmission</td><td><span class=\"kw-clinique\">Morsure</span>, <span class=\"kw-clinique\">griffure</span>, <span class=\"kw-clinique\">léchage</span> sur peau lésée ou muqueuse, par un animal infecté</td></tr>\n          <tr><td>Incubation</td><td>Longue — de <span class=\"kw-chiffre\">10 jours</span> à <span class=\"kw-chiffre\">1 an</span> ; plus courte si la zone d'inoculation est richement innervée (mains, face) ou proche du SNC</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ <strong><span class=\"kw-def\">Épidémiologie</span> France.</strong> La France est <strong>indemne de rage</strong> chez <span class=\"kw-clinique\">les</span> animaux terrestres non volants. Le risque résiduel est lié aux <span class=\"kw-alerte\">chauves-souris</span>, à un <span class=\"kw-alerte\">animal importé</span> d'une zone d'enzootie, ou à une <span class=\"kw-alerte\">morsure à l'étranger</span> en zone d'enzootie. Environ 55 000 décès par an dans le monde.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 175 — Voyage en pays tropical</em></p>","frequence":1},{"id":"173-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les situations à risque et les principes de la prise en charge","contenu":"<div class=\"callout callout-danger\">☠️ <strong><span class=\"kw-alerte\">Urgence</span> absolue.</strong> La rage est <span class=\"kw-alerte\">constamment mortelle une fois les signes cliniques déclarés</span> (tableau d'<span class=\"kw-def\">encéphalite</span>, <span class=\"kw-clinique\">spasme hydrophobique</span> pathognomonique). <span class=\"kw-alerte\">Il n'existe aucun traitement curatif</span> — tout repose sur la prévention post-exposition.</div>\n      <p>Après une exposition à risque, le patient est adressé à un <span class=\"kw-def\">Centre Antirabique (CAR)</span>. La conduite à tenir dépend du niveau de risque :</p>\n      <table >\n        <thead><tr><th>Risque</th><th>Situation</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td>Quasi nul</td><td><span class=\"kw-clinique\">Morsure</span> en France, animal non importé, sans comportement suspect, à disposition, avec un propriétaire</td><td><span class=\"kw-clinique\">Surveillance vétérinaire</span> de l'animal — 3 certificats (<span class=\"kw-chiffre\">J0, J7, J15</span>) ; pas de mesure spécifique</td></tr>\n          <tr><td>Non exclu</td><td>Animal non à disposition (fugue, disparition) mais en France et non importé</td><td><span class=\"kw-ttt\">Vaccination curative</span> — réalisable par tout médecin</td></tr>\n          <tr><td>Élevé</td><td><span class=\"kw-def\">Contact</span> avec une <span class=\"kw-etio\">chauve-souris</span>, contact en zone d'enzootie ou avec un animal importé, animal porteur de rage</td><td>Prise en charge en CAR : <span class=\"kw-ttt\">vaccination curative + sérothérapie</span> par <span class=\"kw-ttt\">Ig spécifiques</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-ttt\">Vaccination</span> curative</strong> — protocole « Essen » en <span class=\"kw-chiffre\">5 injections (J0, J3, J7, J14, J15)</span> ou « 2-1-1 de Zagreb » (2 injections à <span class=\"kw-chiffre\">J0</span> en sites différents, puis J7 et J21) ; <span class=\"kw-chiffre\">2 doses (J0, J3)</span> si vaccination complète antérieure. <strong>Sérothérapie</strong> : <span class=\"kw-ttt\">Ig spécifiques</span> injectées au site de la blessure et en IM à distance, à J0 ; inutile si le sujet est complètement immunisé.</p>\n      <p><strong><span class=\"kw-ttt\">Vaccination préventive</span> (pré-exposition)</strong> : vaccin <span class=\"kw-def\">inerte</span> (virus entier inactivé), recommandé pour <span class=\"kw-clinique\">les</span> séjours prolongés en zone à risque, dès l'âge de la marche chez l'enfant. Elle évite l'administration d'Ig humaines mais <strong>ne dispense pas</strong> d'une <span class=\"kw-ttt\">vaccination</span> post-exposition simplifiée (2 injections de rappel) si morsure à risque.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span></em></p>","frequence":1},{"id":"173-14","rang":"A","rubrique":"Epidémiologie","titre":"Connaître les circonstances imposant la recherche d’une toxoplasmose","contenu":"<p>La <span class=\"kw-def\">toxoplasmose</span> (parasite <span class=\"kw-etio\">Toxoplasma gondii</span>, protozoaire intracellulaire) est une zoonose <strong>cosmopolite</strong>, en règle <strong>bénigne</strong>. Sa recherche s'impose dans <span class=\"kw-clinique\">les</span> <strong>situations où elle peut être grave</strong> :</p>\n      <ul>\n        <li><strong>Femme enceinte</strong> — risque de <span class=\"kw-alerte\">toxoplasmose congénitale</span> : <span class=\"kw-bio\">sérologie</span> obl<span class=\"kw-chiffre\">iga</span>toire au 1ᵉʳ trimestre, puis <span class=\"kw-def\">surveillance</span> mensuelle si la mère n'est pas immune.</li>\n        <li><strong>Patient immunodéprimé</strong> (<span class=\"kw-etio\">VIH</span> avec <span class=\"kw-bio\">CD4 &lt; 200/mm³</span>) — risque de <span class=\"kw-alerte\">réactivation cérébrale</span> : tout tableau neurologique central doit faire évoquer le diagnostic.</li>\n        <li><strong>Bilan pré-transplantation</strong> — statut sérologique du donneur et du receveur d'organe.</li>\n      </ul>\n      <table >\n        <tbody>\n          <tr><td>Réservoirs</td><td><span class=\"kw-etio\">Chat</span> (hôte définitif), <span class=\"kw-etio\">ruminants</span> (bovins, ovins), <span class=\"kw-etio\">porcins</span></td></tr>\n          <tr><td>Transmission</td><td><strong><span class=\"kw-etio\">Oocystes</span> :</strong> litière du chat, crudités souillées par la terre ; <br><strong><span class=\"kw-etio\">Kystes</span> :</strong> viande mal cuite, lait non pasteurisé ; <br><strong>Materno-fœtale :</strong> passage transplacentaire ; <br><strong><span class=\"kw-etio\">Iatrogène</span> :</strong> transfusion sanguine, transplantation d'organe</td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Prévention primaire</span></strong> : viande bien cuite (<span class=\"kw-chiffre\">72 °C</span>) ou congelée (<span class=\"kw-chiffre\">–18 °C</span>), crudités et fruits lavés, lavage des mains et des ustensiles, port de gants pour le changement de litière du chat.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 27 — Prévention risques fœtaux</em></p>","frequence":0},{"id":"173-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","contenu":"<p>Chez le sujet <strong>immunocompétent</strong>, la <span class=\"kw-clinique\">primo-infection</span> toxoplasmique est le plus souvent bénigne.</p>\n      <table >\n        <tbody>\n          <tr><td>Incubation</td><td><span class=\"kw-chiffre\">5 jours à 3 semaines</span> selon le mode de contamination</td></tr>\n          <tr><td>Forme habituelle</td><td><span class=\"kw-clinique\">Asymptomatique</span> dans la majorité des cas</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Manifestations cliniques</strong> (<span class=\"kw-chiffre\">10-20 %</span> des cas) :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span> modérée, <span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">céphalées</span>, arthromyalgies.</li>\n        <li><span class=\"kw-clinique\">Polyadénopathie</span> — notamment <strong>cervicale et occipitale</strong>, pouvant persister plusieurs semaines.</li>\n        <li><span class=\"kw-clinique\">Angine érythémato-pultacée</span>, <span class=\"kw-clinique\">éruption</span> maculo-papuleuse.</li>\n        <li><span class=\"kw-clinique\">Choriorétinite</span> (uvéite postérieure) dans <span class=\"kw-chiffre\">5-10 %</span> des cas.</li>\n      </ul>\n      <p><strong>Manifestations biologiques</strong>, non spécifiques : <span class=\"kw-bio\">syndrome mononucléosique</span> modéré, <span class=\"kw-bio\">hyperéosinophilie</span> modérée, <span class=\"kw-bio\">cytolyse hépatique</span>.</p>\n      <p><strong>Diagnostic</strong> : <span class=\"kw-bio\">sérologie toxoplasmose</span> — <span class=\"kw-chiffre\">IgM</span> positives sans IgG en faveur d'une toxoplasmose en cours (<span class=\"kw-clinique\">les</span> IgG montent ~<span class=\"kw-chiffre\">2 semaines</span> plus tard) ; étude comparative de 2 sérums à<span class=\"kw-chiffre\"> 21 jours</span> d'intervalle si les <span class=\"kw-chiffre\">IgG</span> sont déjà présentes à taux élevé.</p>\n      <div class=\"callout callout-info\">À retenir : chez l'immunocompétent, l'<span class=\"kw-clinique\">évolution</span> est bénigne et il n'y a <strong>pas d'indication de traitement</strong>.</div>","frequence":0},{"id":"173-16","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunodéprimé + femme enceinte","contenu":"<p>Hors de l'immunocompétence, la toxoplasmose devient grave dans deux contextes : l'<strong>immunodépression</strong> et la <strong><span class=\"kw-ci\">grossesse</span></strong>.</p>\n\n      <p><strong>1 · Toxoplasmose cérébrale du sujet immunodéprimé (<span class=\"kw-etio\">VIH</span> ++)</strong></p>\n      <div class=\"callout callout-danger\">⚠️ <strong>Dogme.</strong> Tout tableau <span class=\"kw-alerte\">neurologique central chez un immunodéprimé</span> doit faire évoquer une toxoplasmose cérébrale.</div>\n      <table >\n        <tbody>\n          <tr><td>Mécanisme</td><td>Réactivation (le plus souvent) de kystes tissulaires cérébraux ; survient avec une altération de l'immunité <strong>cellulaire</strong></td></tr>\n          <tr><td>Seuil</td><td>Survient en règle avec des <span class=\"kw-bio\">CD4 &lt; 200/mm³</span></td></tr>\n          <tr><td>Clinique</td><td><span class=\"kw-clinique\">Déficit neurologique focal</span> (<span class=\"kw-chiffre\">50 %</span>), <span class=\"kw-clinique\">céphalées</span> (<span class=\"kw-chiffre\">50-70 %</span>), <span class=\"kw-clinique\">crises convulsives</span> (<span class=\"kw-chiffre\">30 %</span>), <span class=\"kw-clinique\">fièvre</span> inconstante (<span class=\"kw-chiffre\">50 %</span>)</td></tr>\n          <tr><td>Imagerie</td><td><span class=\"kw-imagerie\">IRM / TDM cérébrale</span> avec et sans injection, en <strong><span class=\"kw-alerte\">urgence</span></strong> : <span class=\"kw-clinique\">abcès</span> en <span class=\"kw-radio\">cocarde</span> — centre nécrotique hyposignal, capsule rehaussée par le produit de contraste, <span class=\"kw-clinique\">œdème</span> périlésionnel ; localisations : lobes frontaux, noyaux gris centraux</td></tr>\n          <tr><td>Confirmation</td><td><span class=\"kw-bio\">Sérologie</span> : n'a de valeur que si elle est <strong>négative</strong> (bonne VPN <span class=\"kw-chiffre\">95-97 %</span>) ; <span class=\"kw-bio\">PCR</span> directe (<span class=\"kw-bio\">LCS</span>, <span class=\"kw-bio\">biopsie</span>) ; efficacité du <strong>traitement d'épreuve</strong> ; <span class=\"kw-bio\">biopsie</span> stéréotaxique si pas d'amélioration à <span class=\"kw-chiffre\">J15</span></td></tr>\n          <tr><td>Traitement</td><td><span class=\"kw-ttt\">Pyriméthamine + sulfadiazine</span> + acide <span class=\"kw-ttt\">folinique</span>, pendant <span class=\"kw-chiffre\">3 à 6 semaines</span> (<span class=\"kw-ttt\">clindamycine</span> si <span class=\"kw-ci\">allergie</span> aux <span class=\"kw-ttt\">sulfamides</span>)</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/toxo-cerebrale-cocarde-irm-1.png\" alt=\"IRM cérébrale T1 après gadolinium : abcès toxoplasmique en cocarde avec prise de contraste annulaire\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> cérébrale T1 après gadolinium — <span class=\"kw-clinique\">abcès</span> toxoplasmique en cocarde : capsule rehaussée par le produit de contraste, centre nécrotique en hyposignal. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/toxo-cerebrale-cocarde-irm-2.png\" alt=\"IRM cérébrale T1 après gadolinium : seconde lésion toxoplasmique en cocarde\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">IRM</span> cérébrale T1 après gadolinium — autre coupe : <span class=\"kw-clinique\">lésion</span> en cocarde caractéristique de la toxoplasmose cérébrale du sujet immunodéprimé. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n\n      <p><strong>2 · Toxoplasmose <span class=\"kw-etio\">congénitale</span> (femme enceinte)</strong></p>\n      <p>Elle est liée à une <span class=\"kw-alerte\">primo-infection maternelle</span> survenant pendant la <span class=\"kw-ci\">grossesse</span>.</p>\n      <table >\n        <thead><tr><th>Terme de la contamination</th><th>Risque de transmission</th><th>Sévérité de l'atteinte</th></tr></thead>\n        <tbody>\n          <tr><td>1ᵉʳ trimestre</td><td>Faible (<span class=\"kw-chiffre\">~1-5 %</span>)</td><td><span class=\"kw-alerte\">Sévère — embryo-fœtopathies, avortement</span></td></tr>\n          <tr><td>2ᵉ trimestre</td><td>Intermédiaire (<span class=\"kw-chiffre\">~40 %</span>)</td><td>Fœtopathies ou formes infracliniques</td></tr>\n          <tr><td>3ᵉ trimestre</td><td>Élevé (<span class=\"kw-chiffre\">~70 %</span>)</td><td>Formes sérologiques ou <span class=\"kw-clinique\">choriorétinite</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le risque de transmission <strong>croît avec le terme</strong>, la sévérité de l'atteinte fœtale <strong>décroît avec le terme</strong>.</p>\n      <p><strong><span class=\"kw-def\">Dépistage</span> et prise en charge</strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Sérologie toxoplasmose</span> obl<span class=\"kw-chiffre\">iga</span>toire au 1ᵉʳ trimestre ; si la mère n'est pas immune, <span class=\"kw-def\">surveillance</span> sérologique <strong>mensuelle</strong>.</li>\n        <li>En cas de séroconversion : orientation vers un <span class=\"kw-def\">CPDPN</span> et traitement par <span class=\"kw-ttt\">spiramycine</span> (réduit le risque de transmission).</li>\n        <li>Diagnostic prénatal : <span class=\"kw-imagerie\">échographie</span> mensuelle + <span class=\"kw-bio\">PCR sur amniocentèse</span> (réalisable à partir de 16-18 SA).</li>\n        <li>Si atteinte fœtale confirmée : <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span> ; à la naissance, <span class=\"kw-imagerie\">fond d'œil</span> + <span class=\"kw-imagerie\">échographie</span> transfontanellaire.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 27 — Prévention risques fœtaux · 23 — <span class=\"kw-ci\">Grossesse</span> normale</em></p>","frequence":0},{"id":"173-17","rang":"B","rubrique":"Étiologies","titre":"Connaître les espèces à l’origine des deux formes d’échinococcose","contenu":"<p>L'<span class=\"kw-def\">échinococcose</span> existe sous deux formes, dues à deux espèces distinctes du genre <span class=\"kw-etio\">Echinococcus</span> (<span class=\"kw-def\">cestodes / ténias</span> — plathelminthes segmentés).</p>\n      <table >\n        <thead><tr><th></th><th>Échinococcose hydatique</th><th>Échinococcose alvéolaire</th></tr></thead>\n        <tbody>\n          <tr><td>Agent</td><td><span class=\"kw-etio\">Echinococcus granulosus</span></td><td><span class=\"kw-etio\">Echinococcus multilocularis</span></td></tr>\n          <tr><td>Hôte définitif</td><td><strong><span class=\"kw-etio\">Chien</span></strong></td><td><strong><span class=\"kw-etio\">Renard</span></strong>, <span class=\"kw-etio\">chien</span></td></tr>\n          <tr><td>Hôte intermédiaire</td><td><span class=\"kw-etio\">Mouton</span></td><td><span class=\"kw-etio\">Rongeurs</span></td></tr>\n          <tr><td>Géographie</td><td>Parasitose <span class=\"kw-def\">cosmopolite</span> : régions d'élevage (Maghreb, sud de la France)</td><td>Nord et centre de l'Europe (Vosges, Jura, Alpes, Massif central)</td></tr>\n        </tbody>\n      </table>\n      <p>Dans <span class=\"kw-clinique\">les</span> deux cas, l'<strong>homme est un <span class=\"kw-def\">hôte accidentel</span></strong> (impasse <span class=\"kw-etio\">parasitaire</span>), contaminé par <span class=\"kw-def\">contact</span> direct avec l'hôte définitif ou indirectement via des aliments, l'eau ou des objets souillés par les déjections.</p>","frequence":0},{"id":"173-18","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les localisations préférentielles des échinococcoses","contenu":"<p><span class=\"kw-clinique\">Les</span> deux échinococcoses ont des <strong>localisations préférentielles</strong> distinctes.</p>\n      <p><strong>Échinococcose hydatique (kyste hydatique)</strong> — l'œuf embolise le système circulatoire au niveau du tube digestif, puis se fixe :</p>\n      <table >\n        <thead><tr><th>Localisation</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Foie</span></td><td><span class=\"kw-chiffre\">50-60 %</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Poumon</span></td><td><span class=\"kw-chiffre\">30-40 %</span></td></tr>\n          <tr><td>Autres organes</td><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n        </tbody>\n      </table>\n      <p>Le plus souvent <span class=\"kw-clinique\">asymptomatique</span> (découverte fortuite à l'imagerie) : <span class=\"kw-clinique\">hépatomégalie</span> isolée <span class=\"kw-clinique\">indolore</span> pour la forme hépatique ; <span class=\"kw-clinique\">toux</span>, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-clinique\">hémoptysie</span> pour la forme pulmonaire. À l'<span class=\"kw-imagerie\">imagerie</span>, le kyste peut prendre l'aspect d'un kyste biliaire simple, d'une <span class=\"kw-radio\">paroi calcifiée</span> (kyste mort), ou d'une <span class=\"kw-radio\">membrane décollée ou flottante</span>.</p>\n      <div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> La <span class=\"kw-ci\">ponction d'un kyste hydatique est formellement contre-indiquée</span> — risque de <span class=\"kw-alerte\">dissémination intrapéritonéale</span> et de réaction anaphylactique. Aucune image kystique intrahépatique ne se ponctionne sans <span class=\"kw-bio\">sérologie</span> préalable.</div>\n      <p><strong>Échinococcose alvéolaire</strong> — localisation <strong>intra-hépatique</strong> : <span class=\"kw-clinique\">masse hépatique pseudo-tumorale infiltrante</span>, <span class=\"kw-radio\">mimant une néoplasie</span> à l'imagerie ; complications par <span class=\"kw-alerte\">compression des voies biliaires</span> et des organes adjacents.</p>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/echinocoque-hydatique-1.png\" alt=\"Imagerie d'un kyste hydatique hépatique\" loading=\"lazy\">\n        <figcaption>Kyste hydatique — aspect d'imagerie. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/echinocoque-hydatique-2.png\" alt=\"Imagerie d'un kyste hydatique : décollement de membrane\" loading=\"lazy\">\n        <figcaption>Kyste hydatique — décollement de membrane dans le liquide du kyste. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/echinocoque-hydatique-3.png\" alt=\"Imagerie d'un kyste hydatique\" loading=\"lazy\">\n        <figcaption>Kyste hydatique — aspect d'imagerie. Source : fiche source EDN item 173.</figcaption>\n      </figure>","frequence":0},{"id":"173-19","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir évoquer le diagnostic de leishmaniose cutanée","contenu":"<p>La <span class=\"kw-etio\">leishmaniose</span> est une parasitose due à un protozoaire du genre <span class=\"kw-etio\">Leishmania</span>.</p>\n      <table >\n        <tbody>\n          <tr><td>Vecteur</td><td>Insecte piqueur nocturne — le <span class=\"kw-etio\">phlébotome</span></td></tr>\n          <tr><td>Réservoir</td><td><span class=\"kw-etio\">Chien</span>, <span class=\"kw-etio\">rongeurs</span>, <span class=\"kw-etio\">homme</span></td></tr>\n          <tr><td>Géographie</td><td>Pourtour méditerranéen (France) et zones tropicales (voyageurs)</td></tr>\n          <tr><td>Incubation</td><td><span class=\"kw-chiffre\">Plusieurs semaines</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Leishmaniose cutanée</strong> — à évoquer devant une <span class=\"kw-clinique\">lésion</span> sur une <strong>zone découverte</strong>, évoluant en trois temps :</p>\n      <ol>\n        <li>Une <span class=\"kw-clinique\">papule carmin</span> infiltrée, initialement.</li>\n        <li>Puis une <span class=\"kw-clinique\">ulcération secondaire avec croûte</span>, entourée d'un bourrelet rouge, <strong><span class=\"kw-clinique\">indolore</span></strong>.</li>\n        <li><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-clinique\">chronique</span> sur plusieurs mois.</li>\n      </ol>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/leishmaniose-papule-carmin.png\" alt=\"Leishmaniose cutanée : papule carmin infiltrée sur zone découverte\" loading=\"lazy\">\n        <figcaption>Leishmaniose cutanée — <span class=\"kw-clinique\">papule</span> carmin infiltrée, lésion initiale. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/173/leishmaniose-ulceration-croute.png\" alt=\"Leishmaniose cutanée : ulcération secondaire recouverte d'une croûte\" loading=\"lazy\">\n        <figcaption>Leishmaniose cutanée — <span class=\"kw-clinique\">ulcération</span> secondaire et croûte entourée d'un bourrelet rouge. Source : fiche source EDN item 173.</figcaption>\n      </figure>\n      <p><strong>Diagnostic</strong> : <span class=\"kw-bio\">examen direct</span> sur frottis de grattage du pourtour de la <span class=\"kw-clinique\">lésion</span> ou <span class=\"kw-bio\">biopsie</span> ; <span class=\"kw-bio\">PCR</span> sur la peau.</p>\n      <div class=\"callout callout-info\">Pour contraste : la <strong>leishmaniose viscérale</strong> (kala-azar), plus rare et touchant l'enfant ou l'immunodéprimé, associe <span class=\"kw-clinique\">fièvre</span> hectique, <span class=\"kw-clinique\">splénomégalie</span> et <span class=\"kw-clinique\">pancytopénie</span> ; son diagnostic repose sur le <span class=\"kw-bio\">myélogramme</span> et la <span class=\"kw-bio\">sérologie</span>.</div>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Rage :</strong> <span class=\"kw-alerte\">urgence</span> post-exposition — la maladie est <span class=\"kw-alerte\">constamment mortelle une fois les signes déclarés</span>, sans <span class=\"kw-alerte\">traitement curatif</span>. Désinfection immédiate de la plaie, puis stratification du risque rabique.<br><strong>Pasteurellose :</strong> incubation <span class=\"kw-chiffre\">extrêmement rapide (3 à 6 h)</span> après morsure ou griffure de chat — un <span class=\"kw-clinique\">placard</span> <span class=\"kw-etio\">inflammatoire</span> très précoce impose une consultation sans délai.<br><strong>Toxoplasmose cérébrale :</strong> chez l’immunodéprimé, tout tableau neurologique central impose une <span class=\"kw-imagerie\">IRM/TDM cérébrale</span> en <span class=\"kw-chiffre\">urgence</span>.<br><strong>Kyste hydatique :</strong> <span class=\"kw-ci\">aucune image kystique ne se ponctionne sans sérologie préalable</span> — risque de <span class=\"kw-alerte\">dissémination intrapéritonéale</span> et d’<span class=\"kw-alerte\">anaphylaxie</span>.</p>","hospit":"<p><strong>Rage, risque élevé :</strong> orientation obl<span class=\"kw-chiffre\">iga</span>toire vers un <span class=\"kw-def\">Centre Antirabique (CAR)</span> pour <span class=\"kw-ttt\">vaccination curative + Ig spécifiques</span> ; risque non exclu : <span class=\"kw-ttt\">vaccination curative</span> réalisable par tout médecin.<br><strong>Toxoplasmose &amp; <span class=\"kw-ci\">grossesse</span> :</strong> en cas de séroconversion, orientation vers un <span class=\"kw-def\">CPDPN</span> et <span class=\"kw-ttt\">spiramycine</span> sans attendre <span class=\"kw-clinique\">les</span> résultats du diagnostic anténatal.<br><strong>Toxoplasmose cérébrale :</strong> <span class=\"kw-alerte\">hospitalisation</span>, <span class=\"kw-imagerie\">imagerie</span> urgente et <span class=\"kw-ttt\">traitement d’épreuve</span> ; <span class=\"kw-bio\">biopsie stéréotaxique</span> si pas d’amélioration à <span class=\"kw-chiffre\">J15</span>.<br><strong>Échinococcoses :</strong> prise en charge chirurgicale en milieu spécialisé — <span class=\"kw-ci\">jamais de</span> <span class=\"kw-ttt\">ponction</span> à l’aveugle.<br><strong>Lyme :</strong> ambulatoire à la phase primaire ; les formes disséminées (neuroborréliose) relèvent d’une <span class=\"kw-ttt\">ceftriaxone</span> parentérale.</p>","redflags":"<ul><li><strong>Rage :</strong> <span class=\"kw-alerte\">spasme hydrophobique</span> et tableau d’<span class=\"kw-alerte\">encéphalite</span> = rage déclarée, <span class=\"kw-alerte\">constamment mortelle</span>.</li><li><strong>Pasteurellose :</strong> <span class=\"kw-alerte\">cellulite</span>, <span class=\"kw-alerte\">phlegmon des gaines</span>, <span class=\"kw-alerte\">arthrite</span>, <span class=\"kw-alerte\">bactériémie</span> chez l’immunodéprimé (cirrhotique).</li><li><strong>Toxoplasmose de l’immunodéprimé :</strong> <span class=\"kw-alerte\">déficit neurologique focal</span>, <span class=\"kw-alerte\">crises convulsives</span> avec <span class=\"kw-bio\">CD4 &lt; 200/mm³</span>.</li><li><strong>Toxoplasmose <span class=\"kw-etio\">congénitale</span> :</strong> <span class=\"kw-alerte\">primo-infection maternelle au 1ᵉʳ trimestre</span> — embryo-fœtopathies sévères, avortement.</li><li><strong>Kyste hydatique :</strong> <span class=\"kw-alerte\">rupture ou fissure</span> (<span class=\"kw-alerte\">anaphylaxie</span>) et <span class=\"kw-alerte\">compression des voies biliaires</span>.</li><li><strong><span class=\"kw-clinique\">Fièvre</span> Q chronique :</strong> <span class=\"kw-alerte\">endocardite à hémocultures négatives</span>, infection vasculaire (anévrisme, prothèse).</li></ul>","principes":"<p>Traitement orienté par la zoonose ; molécules, durées et gestes clés ci-dessous.</p><p><strong>Maladie des griffes du chat</strong></p><ul><li><span class=\"kw-ttt\">Azithromycine</span> pendant <span class=\"kw-chiffre\">5 jours</span> — <span class=\"kw-ttt\">antibiothérapie</span> discutée, l’<span class=\"kw-clinique\">évolution</span> étant spontanément favorable.</li></ul><p><strong>Pasteurellose</strong></p><ul><li><span class=\"kw-ttt\">Amoxicilline</span> pendant <span class=\"kw-chiffre\">7 jours</span> ; si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">céphalosporine</span> ou <span class=\"kw-ttt\">doxycycline</span> (<span class=\"kw-clinique\">les</span> cyclines sont l’ATB de choix sur <em>Pasteurella multocida</em>).</li><li>Plaie : désinfection + <span class=\"kw-ttt\">antibioprophylaxie</span> par <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span>.</li></ul><p><strong>Maladie de Lyme</strong></p><ul><li>Phase primaire (<span class=\"kw-clinique\">érythème</span> migrant) — adulte : <span class=\"kw-ttt\">doxycycline</span> per os <span class=\"kw-chiffre\">14 jours</span> (10 j selon la HAS) ; enfant &lt;<span class=\"kw-chiffre\"> 8 ans</span> : <span class=\"kw-ttt\">amoxicilline</span> <span class=\"kw-chiffre\">14 jours</span> (<span class=\"kw-ci\">doxycycline contre-indiquée</span>).</li><li>Phases disséminées (neuroborréliose) : <span class=\"kw-ttt\">ceftriaxone</span> parentérale <span class=\"kw-chiffre\">2 g/j pendant 15-21 j</span> ou <span class=\"kw-ttt\">doxycycline</span> per os.</li><li>Après piqûre : retrait au <span class=\"kw-ttt\">tire-tique</span> + désinfection ; <span class=\"kw-ci\">pas d’antibioprophylaxie post-piqûre</span>.</li></ul><p><strong><span class=\"kw-clinique\">Fièvre</span> Q</strong></p><ul><li>Aiguë : <span class=\"kw-ttt\">doxycycline</span> <span class=\"kw-chiffre\">2 à 3 semaines</span>.</li><li>Chronique (<span class=\"kw-clinique\">endocardite</span>, infection vasculaire) : <span class=\"kw-ttt\">doxycycline + hydroxychloroquine</span>, <span class=\"kw-chiffre\">18 mois</span> (<span class=\"kw-chiffre\">24 mois</span> si matériel).</li><li>Femme enceinte : <span class=\"kw-ttt\">cotrimoxazole</span>.</li></ul><p><strong>Rage (post-exposition)</strong></p><ul><li>Risque non exclu : <span class=\"kw-ttt\">vaccination curative</span> seule, réalisable par tout médecin.</li><li>Risque élevé : en <span class=\"kw-def\">CAR</span> — <span class=\"kw-ttt\">vaccination curative + Ig spécifiques</span> ; protocole « Essen » <span class=\"kw-chiffre\">5 injections (J0, J3, J7, J14, J15)</span> ou « 2-1-1 de Zagreb ».</li><li>Aucun <span class=\"kw-alerte\">traitement curatif</span> une fois la rage déclarée.</li></ul><p><strong>Toxoplasmose</strong></p><ul><li>Immunocompétent : <span class=\"kw-ci\">pas de traitement</span> (<span class=\"kw-clinique\">évolution</span> bénigne).</li><li>Cérébrale (immunodéprimé) : <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span>, <span class=\"kw-chiffre\">3 à 6 semaines</span> (<span class=\"kw-ttt\">clindamycine</span> si <span class=\"kw-ci\">allergie</span> aux <span class=\"kw-ttt\">sulfamides</span>).</li><li><span class=\"kw-ci\">Grossesse</span> — séroconversion : <span class=\"kw-ttt\">spiramycine</span> ; atteinte fœtale confirmée : <span class=\"kw-ttt\">pyriméthamine + sulfadiazine + acide folinique</span>.</li></ul><p><strong>Échinococcose hydatique</strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> ++ : <span class=\"kw-ttt\">exérèse complète sans ouverture du kyste</span> ; <span class=\"kw-ttt\">PAIR</span> (<span class=\"kw-ttt\">ponction</span>-aspiration-injection-réaspiration) si exérèse impossible.</li><li><span class=\"kw-ttt\">Albendazole</span><span class=\"kw-chiffre\"> 1 mois</span> avant et <span class=\"kw-chiffre\">1 mois</span> après le geste, ou prolongé si <span class=\"kw-ttt\">chirurgie</span> impossible.</li></ul><p><strong>Leishmaniose</strong></p><ul><li>Cutanée : traitement local — <span class=\"kw-ttt\">antimonié</span>, <span class=\"kw-ttt\">cryothérapie</span>, <span class=\"kw-ttt\">paromomycine</span> crème.</li><li>Viscérale (kala-azar) : <span class=\"kw-ttt\">amphotéricine B liposomale</span> par voie systémique.</li></ul>","suivi":"<p><strong>Rage (risque quasi nul) :</strong> <span class=\"kw-clinique\">surveillance vétérinaire</span> de l’animal vivant (chien, chat, furet) — 3 certificats à <span class=\"kw-chiffre\">J0, J7, J15</span> ; si mort ou euthanasie : analyse de la tête (<span class=\"kw-bio\">PCR</span>, <span class=\"kw-bio\">immunofluorescence</span>, <span class=\"kw-bio\">culture</span>).<br><strong>Toxoplasmose &amp; <span class=\"kw-ci\">grossesse</span> :</strong> femme non immune → <span class=\"kw-bio\">sérologie mensuelle</span> jusqu’à l’accouchement, avec <span class=\"kw-def\">suivi</span> <span class=\"kw-imagerie\">échographique</span> mensuel.<br><strong>Toxoplasmose cérébrale :</strong> <span class=\"kw-def\">réévaluation</span> clinico-radiologique à <span class=\"kw-chiffre\">J15</span> du <span class=\"kw-ttt\">traitement d’épreuve</span> ; <span class=\"kw-bio\">biopsie stéréotaxique</span> si échec (évoquer un <span class=\"kw-def\">lymphome cérébral</span>).<br><strong>Échinococcose sous albendazole :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-bio\">hépatique</span> et des <span class=\"kw-bio\">leucocytes</span>.<br><strong>Lyme :</strong> pas de <span class=\"kw-bio\">sérologie</span> de contrôle systématique ; <span class=\"kw-ci\">pas de dépistage du sujet exposé asymptomatique</span>.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-173.pdf","label":"Collège Pilly — Zoonoses (item 173, PDF)"},{"href":"https://radiopaedia.org/articles/neurotoxoplasmosis","label":"Radiopaedia : Neurotoxoplasmosis"},{"href":"https://radiopaedia.org/articles/lyme-disease","label":"Radiopaedia : Lyme disease"},{"href":"https://radiopaedia.org/articles/hydatid-disease","label":"Radiopaedia : Hydatid disease"},{"href":"https://radiopaedia.org/articles/alveolar-echinococcosis","label":"Radiopaedia : Alveolar echinococcosis"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Exposition à un animal : morsure, griffure ou léchage — Désinfection immédiate de la plaie, puis évaluation du risque rabique","detail":"<h4>CAT — Exposition à un animal mordeur ou griffeur — Stratifier le risque rabique après morsure, griffure ou léchage sur peau lésée ou muqueuse</h4>","branches":[{"to":"t-declaree","label":"Signes neurologiques de rage déjà présents (encéphalite, hydrophobie)","color":"red"},{"to":"q-risque","label":"Exposition récente, pas de signe de rage","color":"blue"}]},{"id":"t-declaree","kind":"terminal","label":"Rage déclarée — soins de support","color":"red","detail":"<h4>Clinique</h4><ul><li>Tableau d’<span class=\"kw-def\">encéphalite</span> ; <span class=\"kw-clinique\">spasme hydrophobique</span> pathognomonique (contraction du pharynx empêchant la prise de boissons).</li></ul><h4>Conduite</h4><ul><li>Maladie <span class=\"kw-alerte\">constamment mortelle</span> une fois <span class=\"kw-clinique\">les</span> signes déclarés ; <span class=\"kw-alerte\">aucun traitement curatif</span>. Soins de support et palliatifs.</li></ul>"},{"id":"q-risque","kind":"decision","label":"Niveau de risque rabique selon le contexte — France indemne chez les animaux terrestres non volants ; risque lié aux chauves-souris, animaux importés ou morsures en zone d’enzootie","branches":[{"to":"t-surveillance","label":"Risque quasi nul : animal en France, propriétaire, à disposition, sans comportement suspect","color":"green"},{"to":"t-vaccination","label":"Risque non exclu : animal en France non importé, mais non à disposition (fugue, disparition)","color":"amber"},{"to":"q-immun","label":"Risque élevé : chauve-souris, zone d’enzootie, animal importé ou rage confirmée","color":"red"}]},{"id":"t-surveillance","kind":"terminal","label":"Surveillance vétérinaire de l’animal","color":"green","detail":"<h4>Conduite</h4><ul><li>Aucune mesure spécifique tant que l’animal ne développe pas de signe suspect de rage.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Surveillance vétérinaire</span> de l’animal vivant (chien, chat, furet) : 3 certificats à <span class=\"kw-chiffre\">J0</span>, <span class=\"kw-chiffre\">J7</span>, <span class=\"kw-chiffre\">J15</span>.</li></ul><h4>Si mort ou euthanasie</h4><ul><li>Analyse de la tête de l’animal pour diagnostic de certitude : <span class=\"kw-bio\">PCR</span>, <span class=\"kw-bio\">immunofluorescence</span>, <span class=\"kw-bio\">culture</span>.</li></ul>"},{"id":"t-vaccination","kind":"terminal","label":"Vaccination curative (tout médecin)","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vaccination curative antirabique</span> — réalisable par tout médecin, sans recours obl<span class=\"kw-chiffre\">iga</span>toire au CAR.</li></ul><h4>Protocole</h4><ul><li>« Essen » en <span class=\"kw-chiffre\">5 injections (J0, J3, J7, J14, J15)</span> ou « 2-1-1 de Zagreb » (2 injections à <span class=\"kw-chiffre\">J0</span> en sites différents, puis <span class=\"kw-chiffre\">J7</span> et <span class=\"kw-chiffre\">J21</span>).</li></ul>"},{"id":"q-immun","kind":"decision","label":"Patient déjà vacciné en pré-exposition ? — Le statut vaccinal antérieur conditionne l’administration des immunoglobulines","branches":[{"to":"t-car-vacc","label":"Oui — sujet complètement immunisé","color":"red"},{"to":"t-car-ig","label":"Non — sujet non immunisé","color":"red"}]},{"id":"t-car-vacc","kind":"terminal","label":"CAR — vaccination simplifiée, sans Ig","color":"red","detail":"<h4>Orientation</h4><ul><li>Adresser au <span class=\"kw-def\">Centre Antirabique (CAR)</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vaccination</span> post-exposition simplifiée : <span class=\"kw-chiffre\">2 injections de rappel (J0, J3)</span>. Pas de <span class=\"kw-ttt\">sérothérapie</span> — inutile si le sujet est complètement immunisé.</li></ul>"},{"id":"t-car-ig","kind":"terminal","label":"CAR — vaccination curative + Ig spécifiques","color":"red","detail":"<h4>Orientation</h4><ul><li>Prise en charge <strong>uniquement en <span class=\"kw-def\">Centre Antirabique (CAR)</span></strong>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Vaccination curative</span> complète + <span class=\"kw-ttt\">sérothérapie par Ig spécifiques</span> antirabiques, débutées à <span class=\"kw-chiffre\">J0</span>.</li></ul><h4>Modalités Ig</h4><ul><li><span class=\"kw-ttt\">Ig spécifiques</span> injectées au site de la blessure (dedans et autour) et en IM à un site distant du vaccin.</li></ul><h4>Délai</h4><ul><li>Incubation longue (<span class=\"kw-chiffre\">10 jours</span> à <span class=\"kw-chiffre\">1 an</span>), plus courte si zone richement innervée (mains, face) — d’où l’<span class=\"kw-alerte\">urgence</span> de la <span class=\"kw-ttt\">prophylaxie post-exposition</span>.</li></ul>"}]},"cards":[{"i":"1fab8c18667b","n":173,"o":"173-1","u":"Définition","t":"Connaître la définition d’une zoonose","q":"Quels sont les principaux modes de transmission des zoonoses de l'animal à l'homme ?","a":"<ul><li><strong>Transmission directe</strong> par un animal (morsure, griffure, léchage, contact, voie digestive ou inhalée).</li><li><strong>Transmission par un vecteur</strong>, comme un arthropode (tique, phlébotome).</li><li><strong>Pathologie d'inoculation</strong>, par pénétration de l'agent à travers la peau ou les muqueuses.</li></ul>"},{"i":"31450eb68c91","n":173,"o":"173-1","u":"Définition","t":"Connaître la définition d’une zoonose","q":"Quelles sont les trois familles étiologiques principales des agents pathogènes responsables de zoonoses ?","a":"<ul><li><strong>Bactérienne</strong></li><li><strong>Virale</strong></li><li><strong>Parasitaire</strong></li></ul>"},{"i":"3830656f0800","n":173,"o":"173-1","u":"Définition","t":"Connaître la définition d’une zoonose","q":"Quelle est la définition d'une zoonose, en médecine infectieuse ?","a":"<p>Une zoonose est une <strong>maladie infectieuse</strong> transmise par un <strong>agent pathogène</strong> de l'<strong>animal à l'homme</strong>.</p>"},{"i":"73a0487b8b4d","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Comment définir cliniquement la pasteurellose et quel est son agent causal principal ?","a":"<p>La pasteurellose est une <strong>zoonose bactérienne d'inoculation</strong>, survenant classiquement après une <strong>morsure ou une griffure de chat</strong>. L'agent causal est <em><strong>Pasteurella multocida</strong></em>, un bacille à Gram négatif.</p>"},{"i":"7debc391346c","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Quelle est la particularité du délai d'incubation de la pasteurellose et quels sont les signes cliniques locaux initiaux ?","a":"<p>La pasteurellose se caractérise par une <strong>incubation extrêmement rapide</strong>, de l'ordre de <strong>3 à 6 heures</strong> après l'inoculation, un élément très discriminant. Les signes cliniques initiaux sont un <strong>aspect inflammatoire autour de la plaie</strong> d'inoculation, parfois avec un <strong>écoulement</strong>, et souvent associés à une <strong>lymphangite</strong> et des <strong>adénopathies</strong>.</p>"},{"i":"a9f49db09dbe","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Comment établir le diagnostic microbiologique de la pasteurellose ?","a":"<p>Le diagnostic microbiologique de la pasteurellose repose sur la <strong>culture de prélèvements locaux</strong> (de la plaie) et d'<strong>hémocultures</strong>, qui identifieront <em>Pasteurella multocida</em>.</p>"},{"i":"c48cb9470c32","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Quelles sont les complications possibles de la pasteurellose non ou mal traitée ?","a":"<p>Les complications possibles de la pasteurellose sont une <strong>cellulite</strong>, un <strong>phlegmon des gaines</strong> ou une <strong>arthrite</strong>. Chez les patients immunodéprimés (notamment les <strong>cirrhotiques</strong>), une <strong>bactériémie</strong> est à craindre.</p>"},{"i":"c949d772ea4c","n":173,"o":"173-10","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la pasteurellose","q":"Quels animaux constituent le réservoir principal de <i>Pasteurella multocida</i> et quels sont les modes de transmission de la pasteurellose ?","a":"<p>Le réservoir principal de <em>Pasteurella multocida</em> est le <strong>chat</strong> (le plus fréquemment), mais aussi le chien et les oiseaux. La transmission se fait par <strong>morsure, griffure ou piqûre végétale contaminée</strong>.</p>"},{"i":"237ce4bbfadf","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quel est l'agent causal de la rage et ses caractéristiques principales ?","a":"<p>La rage est causée par un <strong>Lyssavirus</strong>, de la famille des <strong>Rhabdoviridae</strong>. C'est un virus <strong>neurotrope</strong>, <strong>fragile</strong> et rapidement détruit dans le milieu extérieur.</p>"},{"i":"5fbee8a7bbbf","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quels sont les risques épidémiologiques résiduels de rage en France ?","a":"<p>Bien que la France soit indemne de rage chez les animaux terrestres non volants, le risque résiduel est lié :</p><ul><li>Aux <strong>chauves-souris</strong>.</li><li>À un <strong>animal importé</strong> d'une zone d'enzootie.</li><li>À une <strong>morsure contractée à l'étranger</strong> dans une zone d'enzootie.</li></ul>"},{"i":"644a70a40d1e","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quels sont les modes de transmission du virus de la rage à l'Homme ?","a":"<ul><li><strong>Morsure</strong> d'un animal infecté.</li><li><strong>Griffure</strong> d'un animal infecté.</li><li><strong>Léchage sur une peau lésée ou une muqueuse</strong> par un animal infecté.</li></ul>"},{"i":"c6870176b292","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quels sont les principaux réservoirs du virus de la rage ?","a":"<p>Les principaux réservoirs du virus de la rage sont les <strong>canidés</strong> (chiens, loups, etc.), le <strong>renard</strong>, et la <strong>chauve-souris</strong>.</p>"},{"i":"ea4a95a5afc3","n":173,"o":"173-12","u":"Epidémiologie","t":"Connaître les modes de transmission de la rage","q":"Quelle est la durée d'incubation de la rage et quels facteurs peuvent la faire varier ?","a":"<p>L'incubation de la rage est généralement <strong>longue</strong>, variant de <strong>10 jours à 1 an</strong>. Elle est plus courte si la zone d'inoculation est <strong>richement innervée</strong> (mains, face) ou proche du <strong>système nerveux central (SNC)</strong>.</p>"},{"i":"4f81a6331561","n":173,"o":"173-14","u":"Epidémiologie","t":"Connaître les circonstances imposant la recherche d’une toxoplasmose","q":"Pour quelle patiente spécifique la recherche d'une toxoplasmose est-elle systématiquement imposée, et pourquoi ?","a":"<p>La recherche d'une toxoplasmose est systématiquement imposée chez la <strong>femme enceinte</strong> en raison du risque de <strong>toxoplasmose congénitale</strong>. Une sérologie est obligatoire au 1er trimestre, avec une surveillance mensuelle si la mère n'est pas immune.</p>"},{"i":"5e51b2d61845","n":173,"o":"173-14","u":"Epidémiologie","t":"Connaître les circonstances imposant la recherche d’une toxoplasmose","q":"En dehors des patients immunodéprimés et des femmes enceintes, dans quelle autre situation clinique la recherche de toxoplasmose est-elle nécessaire ?","a":"<p>La recherche de la toxoplasmose est nécessaire dans le cadre d'un <strong>bilan pré-transplantation</strong>, afin de déterminer le <strong>statut sérologique du donneur et du receveur d'organe</strong>.</p>"},{"i":"f927741037ca","n":173,"o":"173-14","u":"Epidémiologie","t":"Connaître les circonstances imposant la recherche d’une toxoplasmose","q":"Dans quels cas chez un patient immunodéprimé la recherche d'une toxoplasmose doit-elle être systématique ?","a":"<p>Chez un patient <strong>immunodéprimé</strong>, notamment un patient atteint du <strong>VIH avec CD4 &lt; 200/mm³</strong>, la recherche d'une toxoplasmose doit être systématique devant tout <strong>tableau neurologique central</strong>, en raison du risque de <strong>réactivation cérébrale</strong> de la toxoplasmose.</p>"},{"i":"4a3f7b3fba1c","n":173,"o":"173-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","q":"Quelles sont les anomalies biologiques non spécifiques parfois associées à la primo-infection toxoplasmique chez l’immunocompétent ?","a":"<p>Les manifestations biologiques, non spécifiques, peuvent inclure :</p><ul><li>Un <strong>syndrome mononucléosique</strong> modéré.</li><li>Une <strong>hyperéosinophilie</strong> modérée.</li><li>Une <strong>cytolyse hépatique</strong>.</li></ul>"},{"i":"7f99bbb0cf6e","n":173,"o":"173-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","q":"Quelles sont les caractéristiques cliniques de la primo-infection toxoplasmique chez le sujet immunocompétent ?","a":"<p>La primo-infection toxoplasmique est le plus souvent <strong>asymptomatique</strong> (majorité des cas). Lorsqu'elle est symptomatique (10-20% des cas), les manifestations comprennent :</p><ul><li>Une <strong>fièvre modérée</strong>, asthénie, céphalées, arthromyalgies.</li><li>Une <strong>polyadénopathie</strong>, notamment <strong>cervicale et occipitale</strong>, pouvant persister plusieurs semaines.</li><li>Plus rarement, une angine érythémato-pultacée, ou une éruption maculo-papuleuse.</li><li>Une <strong>choriorétinite</strong> (uvéite postérieure) dans 5-10% des cas.</li></ul>"},{"i":"bea8e983c0d4","n":173,"o":"173-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","q":"Comment interpréter la sérologie pour le diagnostic d'une toxoplasmose en cours chez un patient immuncompétent ?","a":"<p>Le diagnostic repose sur la sérologie toxoplasmose. Une toxoplasmose en cours est suggérée par des <strong>IgM positives sans IgG détectables</strong> au début, les IgG montant ~ 2 semaines plus tard.</p><p>En cas d'IgG déjà présentes à taux élevé, une <strong>étude comparative de 2 sérums avec 21 jours d'intervalle</strong> est nécessaire pour objectiver une séroconversion ou une ascension significative des titres.</p>"},{"i":"d8eb9bedfd9e","n":173,"o":"173-15","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de la toxoplasmose chez l’immunocompétent","q":"Quel est le pronostic et la prise en charge thérapeutique de la toxoplasmose chez le sujet immunocompétent ?","a":"<p>Chez le sujet immunocompétent, l'évolution de la toxoplasmose est <strong>bénigne</strong> et <strong>il n'y a pas d'indication de traitement</strong> spécifique.</p>"},{"i":"2138333077c9","n":173,"o":"173-4","u":"Définition","t":"Maladie des griffes du chat : connaître les généralités","q":"Quel est le réservoir principal et les terrains les plus souvent touchés par la maladie des griffes du chat ?","a":"<p>Le réservoir principal est le <strong>chat</strong>, particulièrement le <strong>chaton</strong> et le <strong>jeune chat</strong>. Elle touche surtout l'<strong>enfant</strong> et le <strong>jeune adulte</strong>.</p>"},{"i":"9d2b86942402","n":173,"o":"173-4","u":"Définition","t":"Maladie des griffes du chat : connaître les généralités","q":"Décrivez la physiopathologie de la maladie des griffes du chat en précisant les étapes clé de la transmission à l'homme et l'évolution locale.","a":"<p>La physiopathologie se déroule en quatre temps :</p><ul><li>Bactériémie asymptomatique chez le chat, qui contamine ses griffes.</li><li>Transmission à l'homme par <strong>morsure</strong>, <strong>griffure</strong>, plus rarement léchage de plaie ou piqûre de puces de chat.</li><li>Multiplication de la bactérie dans le <strong>ganglion relais</strong> du territoire de drainage lymphatique.</li><li>Développement d'une <strong>adénopathie inflammatoire</strong> caractérisée histologiquement par un <strong>granulome épithélioïde sans nécrose caséeuse</strong>, une hyperplasie folliculaire et des micro-abcès.</li></ul>"},{"i":"af8898a52264","n":173,"o":"173-4","u":"Définition","t":"Maladie des griffes du chat : connaître les généralités","q":"Quel agent bactérien est responsable de la maladie des griffes du chat et quelques-unes de ses caractéristiques ?","a":"<p>L'agent responsable est <em><strong>Bartonella henselae</strong></em>. C'est une <strong>bactérie intracellulaire</strong>, <strong>non visible à la coloration de Gram</strong>, rendant les hémocultures inefficaces pour son identification.</p>"},{"i":"d72b1723f7c0","n":173,"o":"173-4","u":"Définition","t":"Maladie des griffes du chat : connaître les généralités","q":"Quelle est la définition de la maladie des griffes du chat et son synonyme ?","a":"<p>La maladie des griffes du chat, ou <strong>lymphoréticulose bénigne d'inoculation</strong>, est une <strong>zoonose bactérienne bénigne d'inoculation</strong>.</p>"},{"i":"289654aecb8d","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"Quelle est l'approche diagnostique initiale pour confirmer une maladie des griffes du chat ?","a":"<p>La confirmation d'une maladie des griffes du chat repose en première intention sur la <strong>sérologie</strong>. Cependant, sa sensibilité est faible, et une sérologie négative n'élimine pas le diagnostic.</p>"},{"i":"6d86f2395f84","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"Quelles sont les caractéristiques cliniques de l'adénopathie associée à la maladie des griffes du chat ?","a":"<p>L'adénopathie de la maladie des griffes du chat est généralement localisée au niveau du <strong>ganglion relais</strong>. Elle est :</p><ul><li><strong>Unique</strong> dans 50 % des cas ou multiple sur un seul territoire <strong>unilatéral</strong> (cervical, axillaire, épitrochléen, inguinal).</li><li>Souvent <strong>volumineuse</strong>, ferme, mobile, <strong>inflammatoire</strong> et sensible.</li><li>Parfois en voie de <strong>fistulisation</strong>.</li></ul>"},{"i":"88aa1c319c98","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"En cas de doute diagnostique pour la maladie des griffes du chat, quels sont les examens complémentaires à privilégier pour une confirmation ?","a":"<p>En cas de doute pour la maladie des griffes du chat, il faut privilégier :</p><ul><li>La <strong>PCR spécifique</strong> sur exérèse ou biopsie ganglionnaire pour un <strong>diagnostic de certitude</strong>.</li><li>L'<strong>histologie</strong> montrant un <strong>granulome épithélioïde sans nécrose caséeuse</strong>, ce qui confère une forte présomption diagnostique.</li></ul>"},{"i":"8929203876e6","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"Quels sont les signes cliniques généraux et les formes atypiques de la maladie des griffes du chat ?","a":"<p>Les signes généraux de la maladie des griffes du chat sont discrets et présents dans <strong>50 %</strong> des cas :</p><ul><li>Céphalées.</li><li>Asthénie.</li><li>Fébricule.</li><li>Douleurs abdominales.</li></ul><p>Deux formes cliniques particulières sont à connaître :</p><ul><li>Le <strong>syndrome oculo-glandulaire de Parinaud</strong> (forme ophtalmique, 10 % des cas) avec conjonctivite et adénopathie prétragienne.</li><li>Les <strong>endocardites à hémocultures négatives</strong> (rares).</li></ul>"},{"i":"fc9cf4868192","n":173,"o":"173-5","u":"Diagnostic positif","t":"Maladie des griffes du chat : connaître les modalités du diagnostic de la maladie","q":"Comment se présente la lésion primaire d'inoculation dans la maladie des griffes du chat et où se localise-t-elle généralement ?","a":"<p>La lésion primaire d'inoculation de la maladie des griffes du chat est présente dans <strong>50 %</strong> des cas. Il s'agit d'une <strong>trace de morsure ou de griffure</strong> qui précède souvent une lésion érythémateuse papuleuse.</p>"},{"i":"20002e3a4aed","n":173,"o":"173-6","u":"Epidémiologie","t":"Connaître les modes de transmission de la maladie de Lyme","q":"Comment la transmission de la bactérie de la maladie de Lyme s'opère-t-elle lors d'une piqûre de tique ?","a":"<p>La bactérie est inoculée par <strong>régurgitation</strong> au cours d'un repas sanguin de la tique.</p>"},{"i":"231286b1fd07","n":173,"o":"173-6","u":"Epidémiologie","t":"Connaître les modes de transmission de la maladie de Lyme","q":"Quels sont les facteurs d'exposition favorisant la transmission de la maladie de Lyme en France métropolitaine ?","a":"<p>Les principaux terrains d'exposition sont :</p><ul><li>Les <strong>promenades en forêt</strong>.</li><li>Les <strong>travaux agricoles et forestiers</strong>.</li></ul>"},{"i":"cdde6339d82a","n":173,"o":"173-6","u":"Epidémiologie","t":"Connaître les modes de transmission de la maladie de Lyme","q":"Quel est le vecteur de la bactérie responsable de la maladie de Lyme ?","a":"<p>La bactérie responsable de la maladie de Lyme, <em>Borrelia spp.</em>, est transmise par la piqûre de <strong>tiques du genre Ixodes</strong>.</p>"},{"i":"18cef274279c","n":173,"o":"173-8","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de Lyme","q":"Quelle est la manifestation clinique pathognomonique de la maladie de Lyme et quelles en sont les caractéristiques ?","a":"<p>La manifestation clinique pathognomonique de la maladie de Lyme est l'<strong>érythème migrant</strong>. Ses caractéristiques sont :</p><ul><li>Une <strong>macule érythémateuse</strong> qui s'étend.</li><li>Une <strong>bordure annulaire centrifuge active</strong>.</li><li>Un <strong>centre généralement plus clair</strong>.</li><li>Elle est <strong>indolore et non prurigineuse</strong>.</li><li>Elle touche les membres inférieurs dans 50 % des cas.</li></ul><p>Aucun examen complémentaire n'est justifié à ce stade.</p>"},{"i":"53dd626752e3","n":173,"o":"173-8","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de Lyme","q":"Comment réaliser le diagnostic biologique de la maladie de Lyme et quelles sont ses limites en cas de suspicion de neuroborréliose ?","a":"<p>Le diagnostic biologique repose essentiellement sur une <strong>sérologie en 2 temps</strong> :</p><ul><li><strong>ELISA</strong> : test sensible, réalisé en première intention.</li><li><strong>Western Blot</strong> : test spécifique, réalisé en confirmation.</li></ul><p>La sérologie n'est considérée positive que si les deux tests sont positifs. En cas de suspicion de neuroborréliose, une <strong>ponction lombaire</strong> est réalisée pour rechercher les anticorps dans le liquide céphalorachidien (LCS) et le sang afin d'évaluer une <strong>synthèse intrathécale d'anticorps</strong>. On ne recherche pas directement <em>Borrelia</em> dans le LCS en raison de la mauvaise sensibilité de cette méthode. Les hémocultures ne sont pas pertinentes car les spirochètes ne sont pas visibles à la coloration de Gram.</p>"},{"i":"62854e9fd0f9","n":173,"o":"173-8","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de Lyme","q":"Sur quels critères repose le diagnostic de la maladie de Lyme ?","a":"<p>Le diagnostic de la maladie de Lyme repose sur l'association de <strong>manifestations cliniques compatibles</strong> et d'un <strong>critère microbiologique</strong>. La sérologie seule ne suffit jamais au diagnostic.</p>"},{"i":"9c60d5b88c45","n":173,"o":"173-8","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic clinique et biologique de Lyme","q":"Quels sont les pièges à connaître concernant la fièvre et l'interprétation de la sérologie dans la maladie de Lyme ?","a":"<p>Concernant la fièvre, il n'y en a <strong>pratiquement jamais</strong> dans la maladie de Lyme.</p><p>Concernant la sérologie, elle présente des pièges :</p><ul><li>Elle ne distingue pas l'infection active de la <strong>cicatrice sérologique</strong>.</li><li>Il peut y avoir jusqu'à <strong>15-20 % de faux positifs</strong> chez des sujets exposés asymptomatiques (par exemple, les chasseurs).</li><li>La sérologie <strong>n'est pas indiquée</strong> chez le sujet exposé asymptomatique ni en dépistage systématique.</li></ul>"}]};